const claudeResponse = $input.first().json;
const prevData = $('03 — Préparer prompt Claude').first().json;

const raw = claudeResponse?.content?.[0]?.text || '';
if (!raw) throw new Error('Réponse Claude vide — content[0].text absent');

// Retirer les balises markdown si présentes
const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
const jsonStr = fenceMatch ? fenceMatch[1].trim() : raw.trim();

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('Impossible de parser la réponse Claude : ' + e.message + ' — Extrait : ' + jsonStr.slice(0, 400));
}

if (!Array.isArray(parsed.top_candidats) || parsed.top_candidats.length === 0) {
  throw new Error('Claude batch : top_candidats manquant ou vide dans la réponse');
}

console.log(`✅ Claude a sélectionné ${parsed.top_candidats.length} candidats sur ${prevData.candidatures_count} pour l'offre ${prevData.offre_id}`);

return [{ json: {
  callback_url:      prevData.callback_url,
  callback_secret:   prevData.callback_secret,
  top_candidats:     parsed.top_candidats,
  tous_candidats:    parsed.tous_candidats || [],
  resume_evaluation: parsed.resume_evaluation || ''
}}];
